/* Character inspection keeps the actual model unobstructed, including on phones. */
#portrait-strip{position:fixed;top:132px;left:24px;z-index:12;display:none;align-items:center;gap:12px;padding:10px 12px;max-width:420px;background:#0c1d1ce8;border:1px solid #c8b58155;border-radius:7px;box-shadow:0 8px 24px #0003}
body[data-portrait=true] #portrait-strip{display:flex}body[data-portrait=true] #citizen-card{display:none!important}
#portrait-identity{min-width:0;flex:1}#portrait-name{display:block;font:19px Georgia,serif;color:#f6e4b6}#portrait-task{display:block;font-size:10px;color:#b8c9bc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px;margin-top:4px}
#portrait-strip button{border:1px solid #b5aa7a66;background:#d5b87818;color:#f5dfac;border-radius:5px;padding:9px 10px;min-height:40px;font:11px system-ui;cursor:pointer}#portrait-strip button:focus-visible{outline:2px solid #ffe1a4;outline-offset:2px}
body[data-hud=cinema] #portrait-strip{display:none!important}
@media(max-width:1180px){#portrait-strip{top:155px;left:20px}}
@media(max-width:700px){#portrait-strip{top:198px;left:12px;right:12px;max-width:none;padding:7px 9px;gap:8px}#portrait-name{font-size:17px}#portrait-task{max-width:180px;font-size:9px}#portrait-strip button{padding:7px 9px;font-size:10px}}

const districtStats={plantedBorders:0,plants:0,landscapeTriangles:0,dormers:0};
function cottageDormer(x,z,scale,variant){
 if(variant===0||scale>1.2)return;
 const w=(2.4+variant*.42)*scale,y=terrain(x,z)+1.9*scale,side=variant===1?-1:1;
 const front=x+side*w*.40,back=x+side*w*.04,cz=z+(variant===1?-.30:.20)*scale,half=.35*scale;
 const bottom=y+.25*scale,eave=y+.78*scale,peak=y+1.09*scale,backPeak=y+1.30*scale;
 const plaster=rgb(0xc9b790),timber=rgb(0x594837),slate=rgb(variant===1?0x6c7978:0x9e7252);
 // Side cheeks tuck into the existing slope. The window sits above that slope.
 for(const edge of [-1,1]){
  const zz=cz+edge*half;
  const a=[front,bottom,zz],b=[back,y+1.13*scale,zz],c=[back,y+1.20*scale,zz],d=[front,eave,zz];
  quad(a,b,c,d,plaster);quad(d,c,b,a,plaster);
  const r0=[front,eave,zz],r1=[front,peak,cz],r2=[back,backPeak,cz],r3=[back,y+1.20*scale,zz];
  materialScope(MATERIAL.ROOF,()=>{quad(r0,r1,r2,r3,slate);quad(r3,r2,r1,r0,slate)});
  limbSegment(r0,r1,.034*scale,timber,5);
 }
 const a=[front,bottom,cz-half],b=[front,bottom,cz+half],c=[front,eave,cz+half],d=[front,eave,cz-half];
 quad(a,b,c,d,plaster);quad(d,c,b,a,plaster);
 tri(d,c,[front,peak,cz],plaster);tri(c,d,[front,peak,cz],plaster);
 box(front+side*.025*scale,bottom+.10*scale,cz,.045*scale,.39*scale,.39*scale,rgb(0x3e6267));
 for(const edge of [-1,1])box(front+side*.055*scale,bottom+.06*scale,cz+edge*.24*scale,.07*scale,.48*scale,.055*scale,timber);
 box(front+side*.06*scale,bottom+.06*scale,cz,.075*scale,.052*scale,.53*scale,timber);
 box(front+side*.06*scale,bottom+.52*scale,cz,.075*scale,.052*scale,.53*scale,timber);
 box(front+side*.065*scale,bottom+.1*scale,cz,.038*scale,.39*scale,.028*scale,rgb(0xcbbd91));
 districtStats.dormers++;
}

const livingForest={forestTrees:0,canopyLobes:0,understoryPatches:0,forestTriangles:0};
// Original alpha-tested leaf atlas. Crossed, world-fixed cards preserve depth
// and cast the same cutout silhouettes in the sun pass. No downloaded assets.
const leafLayer={vertices:[],cards:0,uploads:0,draws:0,depthDraws:0,textureWidth:512,textureHeight:256,supported:gpuAvailable};
function makeLeafAtlas(){
 const atlas=document.createElement('canvas');atlas.width=512;atlas.height=256;
 const ctx=atlas.getContext('2d');
 const leaf=(x,y,length,angle,width,tone)=>{
  ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.beginPath();ctx.moveTo(0,0);
  ctx.bezierCurveTo(length*.28,-width,length*.72,-width,length,0);
  ctx.bezierCurveTo(length*.65,width*.75,length*.30,width*.85,0,0);
  ctx.fillStyle=tone;ctx.fill();ctx.strokeStyle='#bad09266';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(1,0);ctx.lineTo(length*.92,0);ctx.stroke();ctx.restore();
 };
 // Broadleaf branch: fine stems support overlapping leaves and broken edges.
 ctx.save();ctx.beginPath();ctx.rect(2,2,252,252);ctx.clip();
 for(let branch=0;branch<11;branch++){
  const angle=-2.8+branch*.53,len=65+biomeHash(branch+21)*42,ox=128,oy=139;
  ctx.strokeStyle='#666c43';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(ox+Math.cos(angle)*len,oy+Math.sin(angle)*len);ctx.stroke();
  for(let n=0;n<13;n++){
   const f=.22+n*.059,h=biomeHash(branch*47+n*13),x=ox+Math.cos(angle)*len*f+(h-.5)*13,y=oy+Math.sin(angle)*len*f+(biomeHash(n+branch*71)-.5)*12;
   const side=n%2?1:-1,c=['#a3b57b','#c2cf92','#8eab6d','#d0dba3'][Math.floor(h*4)];
   leaf(x,y,15+h*16,angle+side*(.63+h*.45),5+h*6,c);
